'use strict';
let courseMaterials=[],courseJob=null,courseGenerated=null,coursePollTimer=null,courseTitleDraft='',coursePasteDraft='';
const legacyMaterialImport=importMaterial;
function courseCopy(zh,en){return state.language==='en'?en:zh;}
async function showCourseImporter(){
 if(courseGenerated){showCoursePreview();return;}
 modal(`<span class="eyebrow">${courseCopy('我的整套知识库','My complete knowledge library')}</span><h2 id="dialogTitle">${courseCopy('带来教材，开启一门新的游戏课程','Bring your materials and create a game course')}</h2><p>${courseCopy('可一次选择多份文件、拖入资料，或直接粘贴整段笔记。先建立知识库、核对缺口，再生成章节与交互；你预览确认后才加入游戏。','Select several files, drop them here or paste your notes. The service first builds a knowledge inventory and checks gaps, then designs chapters and activities. You preview and confirm before adding the course.')}</p><div class="course-import-steps"><span>${courseCopy('① 放入整套资料','1. Add your materials')}</span><span>${courseCopy('② 整理知识与缺口','2. Check knowledge and gaps')}</span><span>${courseCopy('③ 生成并核对课程','3. Generate and review')}</span></div><label class="form-label" for="courseTitle">${courseCopy('课程名称','Course title')}</label><input id="courseTitle" value="${esc(courseTitleDraft||courseCopy('我的学习课程','My learning course'))}"><div id="courseDrop" class="course-drop-zone">${courseCopy('拖入整套学习资料，或选择多个文件','Drop your learning materials or select several files')}<br><input id="courseFiles" type="file" multiple accept=".txt,.md,.csv,.json" aria-label="${courseCopy('选择多份知识库材料','Select knowledge library files')}"><small>${courseCopy('TXT / Markdown / CSV / JSON · 最多50份、合计7MB · PDF或扫描件请先提取文字','TXT / Markdown / CSV / JSON · up to 50 materials and 7 MB total · extract text from PDFs or scans first')}</small></div><section class="course-paste"><label class="form-label" for="coursePaste">${courseCopy('也可以直接粘贴知识库正文','Or paste your knowledge library text')}</label><textarea id="coursePaste" placeholder="${courseCopy('粘贴教材、讲义或笔记正文，再点击下方按钮加入材料清单。','Paste textbook content, lecture notes or study notes, then add them to the material list.')}">${esc(coursePasteDraft)}</textarea><button id="addCourseText">${courseCopy('把这段文字加入资料','Add this text to materials')}</button></section><div id="courseFileList" aria-live="polite"></div><p id="courseMaterialStatus" role="status"></p><p id="courseAPIStatus" class="note">${courseCopy('正在检查课程生成服务…','Checking the course generation service…')}</p><div id="courseJobStatus" class="course-progress" role="status" aria-live="polite"></div><div class="actions"><button id="generateCourse" class="primary" disabled>${courseCopy('用这些资料生成游戏课程','Generate a game course from these materials')}</button><button id="cancelCourseJob" ${courseJob?'':'disabled'}>${courseCopy('取消生成','Cancel generation')}</button><button id="legacyMaterial">${courseCopy('导入已有题库','Import an existing question bank')}</button></div><p class="muted">${courseCopy('只有点击生成后，材料才会发送到你配置的模型服务；当前材料清单关闭窗口后仍可继续编辑，刷新页面会清空。生成课程不会覆盖已有进度。','Materials are sent to your configured model service only when you generate. You can close and reopen this list; reloading the page clears it. A new course does not overwrite existing progress.')}</p>`,true);
 $('courseTitle').oninput=()=>{courseTitleDraft=$('courseTitle').value;};$('coursePaste').oninput=()=>{coursePasteDraft=$('coursePaste').value;};$('courseFiles').onchange=e=>readCourseFiles(e.target.files);
 const drop=$('courseDrop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();e.stopPropagation();drop.classList.remove('dragover');readCourseFiles(e.dataTransfer.files);};
 $('addCourseText').onclick=()=>{const text=$('coursePaste').value;if(!text.trim()){courseMaterialMessage(courseCopy('先粘贴正文，再加入资料。','Paste some text before adding it.'));return;}let number=1;while(courseMaterials.some(m=>m.name==='notes-'+number+'.txt'))number++;if(addCourseMaterials([{name:'notes-'+number+'.txt',text}])){coursePasteDraft='';$('coursePaste').value='';}};
 $('legacyMaterial').onclick=legacyMaterialImport;$('cancelCourseJob').onclick=cancelGeneratedCourse;renderCourseFileList();
 try{const response=await fetch('/api/config');if(!response.ok)throw Error();const config=await response.json();if(!$('courseAPIStatus'))return;$('courseAPIStatus').textContent=config.configured?courseCopy(`生成服务已连接：${config.service} · ${config.model}。资料按片段先建知识库，再组织课程。`,`Service connected: ${config.service} · ${config.model}. Each material segment is inventoried before course design.`):courseCopy('资料可以先放进来。AI生成尚未启用：请在本机 .env 填写 API_BASE_URL、API_MODEL、API_KEY 并重启服务；配置完成后才能把资料转成课程。','You can add materials now. AI generation is not configured: set API_BASE_URL, API_MODEL and API_KEY in your local .env, then restart the server to generate courses.');$('generateCourse').disabled=!config.configured||!!courseJob;$('generateCourse').onclick=startGeneratedCourse;if(courseJob)pollGeneratedCourse();}
 catch{if($('courseAPIStatus'))$('courseAPIStatus').textContent=courseCopy('资料可先选择；课程生成需要本机服务。运行 npm start 后打开 http://127.0.0.1:8766，再配置模型接口。','You can select materials now. Generation needs the local server: run npm start, open http://127.0.0.1:8766 and configure your model service.');}
}
function courseMaterialMessage(message){if($('courseMaterialStatus'))$('courseMaterialStatus').textContent=message;else toast(message);}
function addCourseMaterials(incoming){incoming=[...new Map(incoming.map(m=>[m.name,m])).values()];const names=new Set(incoming.map(m=>m.name)),next=[...courseMaterials.filter(m=>!names.has(m.name)),...incoming];if(next.length>50||next.reduce((n,m)=>n+new TextEncoder().encode(m.text).length,0)>7*1024*1024){courseMaterialMessage(courseCopy('资料最多50份、合计7MB。原有清单已保留，请分课程导入。','Use up to 50 materials and 7 MB total. Your existing list is preserved; split larger libraries into courses.'));return false;}if(next.some(m=>!m.text.trim())){courseMaterialMessage(courseCopy('有资料没有可读文字，请先检查文件。','A material contains no readable text. Check the file first.'));return false;}courseMaterials=next;renderCourseFileList();courseMaterialMessage(courseCopy('资料已加入；可以继续追加文件或文字。同名文件会替换清单中的旧文件。','Materials added. Keep adding files or text; a same-named file replaces the previous version in this list.'));return true;}
async function readCourseFiles(fileList){const files=[...(fileList||[])];if(!files.length)return;if(files.length>50||files.reduce((n,f)=>n+f.size,0)>7*1024*1024){courseMaterialMessage(courseCopy('每次最多50份文字文件、合计7MB，请按课程拆分。','Select up to 50 text files and 7 MB total; split larger libraries into courses.'));return;}if(files.some(f=>! /\.(txt|md|csv|json)$/i.test(f.name))){courseMaterialMessage(courseCopy('请先将PDF、图片或其他文件转成文字，再上传TXT、Markdown、CSV或JSON。','Extract text from PDFs, images or other formats before uploading TXT, Markdown, CSV or JSON.'));return;}try{addCourseMaterials(await Promise.all(files.map(async f=>({name:f.name,text:await f.text()}))));}catch{courseMaterialMessage(courseCopy('文件读取失败；已添加的资料仍在，请检查文件后重试。','Could not read a file. Existing materials are preserved; check the file and retry.'));}}
function renderCourseFileList(){const host=$('courseFileList');if(!host)return;host.innerHTML=courseMaterials.length?`<h3>${courseCopy('待生成的知识库','Knowledge library to generate')} · ${courseMaterials.length}/50</h3><p>${courseCopy('已加入文字','Text added')} ${(courseMaterials.reduce((n,m)=>n+new TextEncoder().encode(m.text).length,0)/1024).toFixed(1)} KB / 7 MB</p>${courseMaterials.map((m,i)=>`<div class="course-file-row"><span>${esc(m.name)}<small>${m.text.length.toLocaleString()} ${courseCopy('字符','characters')}</small></span><button data-remove-course-material="${i}" aria-label="${esc(courseCopy('移除资料：','Remove material: ')+m.name)}">${courseCopy('移除','Remove')}</button></div>`).join('')}`:`<p>${courseCopy('还没有放入资料。可以选择文件或粘贴正文。','No materials yet. Select files or paste your text.')}</p>`;document.querySelectorAll('[data-remove-course-material]').forEach(el=>el.onclick=()=>{courseMaterials.splice(+el.dataset.removeCourseMaterial,1);renderCourseFileList();});}
async function startGeneratedCourse(){if(courseJob)return;if(!courseMaterials.length){$('courseJobStatus').textContent='请先选择至少一份学习材料。';return;}$('generateCourse').disabled=true;$('courseJobStatus').textContent='正在提交课程生成任务…';try{const r=await fetch('/api/course-jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:$('courseTitle').value.trim()||'我的学习课程',materials:courseMaterials})}),data=await r.json();if(!r.ok)throw Error(data.error||'无法提交生成任务。');courseJob=data.id;if($('cancelCourseJob'))$('cancelCourseJob').disabled=false;pollGeneratedCourse();}catch(error){if($('courseJobStatus'))$('courseJobStatus').textContent=error.message;if($('generateCourse'))$('generateCourse').disabled=false;}}
async function pollGeneratedCourse(){clearTimeout(coursePollTimer);const id=courseJob;if(!id)return;try{const r=await fetch('/api/course-jobs/'+encodeURIComponent(id)),data=await r.json();if(courseJob!==id)return;if(!r.ok)throw Error(data.error||'读取任务失败。');if(data.status==='done'){courseGenerated=CourseSchema.normalize(data.course);courseJob=null;if($('courseJobStatus'))showCoursePreview();else toast('课程已整理好，可从“导入材料”打开预览并核对。');return;}if(['failed','cancelled'].includes(data.status))throw Error(data.error||'生成已取消。');if($('courseJobStatus'))$('courseJobStatus').textContent=`${data.phase==='inventory'?'正在逐项建立知识库并核对出处':'知识库已整理，正在组织章节和交互'} · ${data.done}/${data.total||'…'} 步`;coursePollTimer=setTimeout(pollGeneratedCourse,1500);}catch(error){courseJob=null;if($('courseJobStatus'))$('courseJobStatus').textContent=error.message;if($('generateCourse'))$('generateCourse').disabled=false;}}
async function cancelGeneratedCourse(){clearTimeout(coursePollTimer);const id=courseJob;courseJob=null;if(id)try{await fetch('/api/course-jobs/'+encodeURIComponent(id),{method:'DELETE'});}catch{}if($('courseJobStatus'))$('courseJobStatus').textContent='已取消生成；原有课程与进度保持不变。';if($('generateCourse'))$('generateCourse').disabled=false;}
function showCoursePreview(){const course=courseGenerated;if(!course)return;modal(`<span class="eyebrow">课程预览 · 先核对再加入</span><h2 id="dialogTitle">${esc(course.title)}</h2><p>按章节检查基础解释、例子、练习及原文引用。AI整理可能出错；只有你确认后才创建新课程。</p><div class="course-preview">${course.chapters.map((ch,i)=>`<article><h3>第 ${i+1} 章 · ${esc(ch.title)}</h3>${ch.sections.map(sec=>`<details><summary>${esc(sec.id+' '+sec.title)} · ${sec.lessons.length} 张基础卡 / ${sec.questions.length} 题</summary>${sec.activity?`<p>情境装置：${esc(sec.activity.title.zh)} · ${sec.activity.rounds.length} 轮</p><details><summary>核对操作与判定说明</summary>${sec.activity.rounds.map(r=>`<p><strong>${esc(r.type)}</strong> · ${esc(r.prompt.zh)}</p><p>${esc(r.reason.zh)}</p>`).join('')}</details>`:''}${sec.lessons.map(l=>`<details><summary>${esc(l.title)}</summary><p>${esc(l.body)}</p><p>${esc(l.example)}</p><blockquote>${esc(l.quote)}</blockquote><small>${esc(l.source)}</small></details>`).join('')}<details><summary>核对本节练习与答案</summary>${sec.questions.map(q=>`<div class="item-row"><strong>${esc(q.q)}</strong><p>${esc(learningAnswer(q))}</p><blockquote>${esc(q.quote)}</blockquote></div>`).join('')}</details></details>`).join('')}</article>`).join('')}</div><label class="form-label"><input id="confirmCourse" type="checkbox"> 我已核对内容、顺序与原文，确认加入为一门新课程。</label><div class="actions"><button id="discardCoursePreview">返回材料，不加入</button><button id="commitCourse" class="primary" disabled>加入课程，从第一章基础开始</button></div>`,true);$('confirmCourse').onchange=()=>{$('commitCourse').disabled=!$('confirmCourse').checked;};$('discardCoursePreview').onclick=()=>{courseGenerated=null;showCourseImporter();};$('commitCourse').onclick=()=>{try{const normalized=CourseSchema.normalize(course),b=L.addBank(state,{title:normalized.title,kind:'API整理 · 已由用户核对',cards:CourseSchema.cards(normalized)},Date.now());b.syllabus=normalized;b.focus=normalized.chapters[0].sections[0].id;state.chapterStudies??={};state.chapterStudies[b.id]=CS.fresh();L.start(state,Date.now(),true);A.session(state);activeQuest=null;selectedPiece=null;selectedTool=null;state.zone=normalized.chapters[0].zone;state.guide=true;courseGenerated=null;close();renderWorld();resetCamera();save();toast('课程已加入。可以自由选择章节；每章先阅读基础，再解锁本章练习。');}catch(error){toast(error.message);}};}
importMaterial=showCourseImporter;
$('importKnowledge').onclick=()=>{if(typeof activeAwayScene!=='undefined'&&activeAwayScene)closeAwayScene();showCourseImporter();};
document.addEventListener('dragover',e=>{if(e.dataTransfer?.types?.includes('Files'))e.preventDefault();});
document.addEventListener('drop',e=>{if(!e.dataTransfer?.files?.length)return;e.preventDefault();showCourseImporter();readCourseFiles(e.dataTransfer.files);});
